import { Book } from "@/lib/types";

export const nehemiah: Book = {
  id: "nehemiah",
  name: "Nehemia",
  shortName: "Neh",
  testament: "old",
  introduction: `Wiederaufbau von Jerusalem\nDreizehn Jahre nach Esra kam Nehemia im Jahr 444 v.Chr. nach Jerusalem. Er hatte von dem Zustand Jerusalems und dem Baustopp gehört und konnte beim König dessen Aufhebung erwirken. In nur 52 Tagen baute er mit den Juden die Mauer Jerusalems wieder auf. Er wurde von Gott vor allem dazu gebraucht, die sozialen, wirtschaftlichen und gottesdienstlichen Verhältnisse in seinem Volk zu ordnen. **Nehemia schrieb sein Buch** wahrscheinlich bald nach den darin geschilderten Ereignissen, vermutlich kurz nach dem Jahr 430 v.Chr. auf. Dabei arbeitete er auch offizielle Listen ein. Meist schrieb er in der Ich-Form, also 1. Person Einzahl, benutzte aber auch die 3. Person (Kap. 8), was damals nicht unüblich war. Den Schluss bilden die Aufzeichnungen Nehemias aus seinem zweiten Aufenthalt in Jerusalem, der um 430 v.Chr. begann.\n****Wie Nehemia, ein genialer Führer, die Stadt Jerusalem wiederbelebt.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Bericht von Nehemia Ben-Hachalja: Im 20. Regierungsjahr des Artaxerxes* hielt ich mich in der befestigten Oberstadt von Susa* auf. Im Dezember*", heading: "1-7: Wiederaufbau der Mauer um Jerusalem\nNehemias Gebet", footnotes: ["Artaxerxes. Persischer König von 465-424 v.Chr. Sein 20. Regierungsjahr dauerte vom 13. April 445 v.Chr. bis zum 2. April 444 v.Chr.", "Darius I. hatte Susa zur Hauptstadt des persischen Weltreichs gemacht. Die Oberstadt mit dem befestigten Palastquartier lag 24 Meter über der Stadt und der eigentliche Palast noch einmal 16 Meter höher.", "Dezember. Wörtlich: im Monat Kislew. Es war im Jahr 445 v.Chr. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers."] },
      { number: 2, text: "kam Hanani, einer meiner Brüder, mit einigen Männern aus Judäa zu mir. Ich fragte sie, wie es den Juden dort ginge, dem Rest, der dem Exil entkommen war, und erkundigte mich nach Jerusalem." },
      { number: 3, text: "Sie berichteten: \"Die Juden dort in der Provinz leben in großer Not und Schande. Die Mauer Jerusalems liegt immer noch in Trümmern und die Tore sind verbrannt.\"" },
      { number: 4, text: "Als ich das hörte, setzte ich mich hin und weinte. Ich trauerte tagelang, fastete und betete zu Gott im Himmel." },
      { number: 5, text: "Ich sagte: \"Ach Jahwe, du Gott des Himmels, du großer und furchterregender Gott! Du stehst zu deinem Gnadenbund und zu denen, die dich lieben und deine Gebote halten!" },
      { number: 6, text: "Hab doch ein offenes Ohr für mein Gebet und sieh deinen Diener freundlich an. Tag und Nacht flehe ich zu dir für deine Diener, die Israeliten. Und ich bekenne die Sünden, die wir gegen dich begangen haben, auch ich und meine Familie." },
      { number: 7, text: "Wir haben uns schwer an dir vergangen; wir haben die Gebote, Gesetze und Anordnungen missachtet, die du deinem Diener Mose gegeben hast." },
      { number: 8, text: "Denk doch an das, was du ihm damals gesagt hast: 'Wenn ihr mir die Treue brecht, dann werde ich euch unter die Völker zerstreuen." },
      { number: 9, text: "Wenn ihr aber wieder zu mir umkehrt und meine Gebote achtet und befolgt, dann werde ich euch wieder zurückholen, selbst die, die ich bis zum fernsten Horizont verstoßen habe. Ich werde sie heimbringen an den Ort, den ich zum Wohnsitz meines Namens erwählt habe.' –" },
      { number: 10, text: "Sie sind ja doch deine Diener und dein Volk, das du durch deine große Macht und mit starker Hand befreit hast." },
      { number: 11, text: "Ach Jahwe, erhöre mein Gebet und das Flehen deiner Diener, die dir ehrfürchtig dienen wollen. Lass es mir, deinem Diener, doch heute gelingen, dass er bei diesem Mann Erbarmen findet.\" Ich war nämlich Mundschenk beim König." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Es war im 20. Regierungsjahr des Königs Artaxerxes, im April*. Als der Wein gebracht wurde, füllte ich den Becher und reichte ihn dem König. Der König hatte mich in seiner Gegenwart noch nie traurig gesehen,", heading: "Rückreise nach Jerusalem", footnotes: ["April. Wörtlich: im Monat Nisan. Es war das Jahr 444 v.Chr."] },
      { number: 2, text: "deshalb fragte er mich: \"Warum siehst du so bedrückt aus? Du bist doch nicht etwa krank? Nein, dich belastet etwas anderes.\" Ich erschrak heftig" },
      { number: 3, text: "und antwortete: \"Der König möge ewig leben! Wie könnte ich froh sein, wenn die Stadt, in der meine Vorfahren begraben liegen, ein Trümmerhaufen ist und ihre Tore verbrannt sind?\"" },
      { number: 4, text: "Der König sagte: \"Und was ist deine Bitte?\" Da betete ich zu Gott im Himmel" },
      { number: 5, text: "und erwiderte dem König: \"Wenn der König es für gut hält und wenn du mir, deinem Diener, vertraust, dann sende mich doch nach Judäa in die Stadt, in der meine Vorfahren begraben liegen. Ich möchte die Stadt wieder aufbauen!\"" },
      { number: 6, text: "Der König fragte mich – die Königin saß übrigens neben ihm: \"Wie lange würde deine Reise dauern? Wann würdest du wieder zurück sein?\" Ich nannte ihm eine Zeit. Der König war einverstanden und wollte mich ziehen lassen." },
      { number: 7, text: "Ich sagte noch zu ihm: \"Wenn es dem König recht ist, gebe man mir Briefe an die Statthalter der Westeuphrat-Provinz mit, damit sie mich nach Judäa durchreisen lassen," },
      { number: 8, text: "und einen Brief an Asaf, den Verwalter der königlichen Wälder, damit er mir Bauholz für die Tore der Tempelburg liefert, für die Stadtmauer und für das Haus, in dem ich wohnen werde.\" Der König gewährte mir alles, weil die gütige Hand meines Gottes über mir war." },
      { number: 9, text: "So kam ich zu den Statthaltern der Westeuphrat-Provinz und überreichte ihnen die Briefe des Königs, der mir übrigens eine Reitertruppe mitgegeben hatte." },
      { number: 10, text: "Der Horoniter Sanballat und der Ammoniter Tobija, sein Beauftragter, gerieten in heftigen Zorn, als sie merkten, dass da ein Mensch gekommen war, der sich für das Wohl der Israeliten einsetzte." },
      { number: 11, text: "Als ich in Jerusalem angekommen war und drei Tage dort zugebracht hatte,", heading: "Entschluss zum Mauerbau" },
      { number: 12, text: "machte ich mich nachts mit einigen wenigen Männern auf. Nur ich hatte ein Reittier dabei. Bis dahin hatte ich noch keinem Menschen gesagt, was Gott mir ins Herz gegeben hatte, für Jerusalem zu tun." },
      { number: 13, text: "So ritt ich bei Nacht durch das Taltor in Richtung Drachenquelle bis zum Misttor. Ich untersuchte die niedergerissene Mauer und die vom Feuer vernichteten Tore." },
      { number: 14, text: "Dann zog ich zum Quellentor hinüber und zum Königsteich. Als dort für mein Tier kein Durchkommen mehr war," },
      { number: 15, text: "stieg ich bei Nacht zu Fuß die Schlucht hinauf und untersuchte die Mauer. Dann kehrte ich um und kam durch das Taltor wieder zurück." },
      { number: 16, text: "Die Vorsteher wussten nicht, wohin ich gegangen war und was ich tun wollte. Denn bis dahin hatte ich keinem Juden etwas von meinem Vorhaben erzählt, weder den Priestern noch den Vornehmen, weder den Vorstehern noch den übrigen, die an dem Werk mitarbeiten sollten." },
      { number: 17, text: "Jetzt aber sagte ich zu ihnen: \"Ihr seht das Elend, in dem wir uns befinden. Jerusalem liegt in Trümmern und seine Tore sind verbrannt. Kommt, lasst uns die Mauer wieder aufbauen, damit wir nicht länger dem Spott der Leute preisgegeben sind!\"" },
      { number: 18, text: "Ich erzählte ihnen, wie Gottes gütige Hand über mir gewesen war und was der König mir gewährt hatte. Da sagten sie: \"Gut, machen wir uns ans Werk! Bauen wir!\" Und sie ermutigten sich gegenseitig, dieses gute Werk zu beginnen." },
      { number: 19, text: "Als der Horoniter Sanballat, der Ammoniter Tobija, sein Beauftragter, und der Araber Geschem davon hörten, lachten sie uns aus und spotteten: \"Da habt ihr euch ja einiges vorgenommen! Gegen den König wollt ihr euch auflehnen?\"" },
      { number: 20, text: "Ich ließ ihnen antworten: \"Der Gott des Himmels wird es uns gelingen lassen. Und wir, seine Diener, werden ans Werk gehen und bauen. Euch jedoch geht Jerusalem nichts an. Ihr habt hier weder Grundbesitz noch Anspruch noch irgendein historisches Recht an der Stadt.\"" },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Der Hohe Priester Eljaschib baute zusammen mit seinen Mitpriestern das Schaftor wieder auf. Dann weihten sie es und setzten seine Torflügel ein. Auch den angrenzenden Mauerabschnitt bis zum Turm der Hundert und dem Hananel-Turm weihten sie ein.", heading: "Wiederaufbau der Stadtmauer" },
      { number: 2, text: "Den anschließenden Mauerabschnitt bauten die Männer von Jericho, und daneben baute Sakkur Ben-Imri." },
      { number: 3, text: "Die Sippe Senaa baute das Fischtor wieder auf. Sie setzten die Balken und die Torflügel ein und brachten Riegel und Sperrbalken an." },
      { number: 4, text: "Neben ihnen arbeitete Meremot Ben-Urija, der Enkel des Hakkoz. Daneben baute Meschullam Ben-Berechja, der Enkel von Meschesabel. Den nächsten Abschnitt setzte Zadok Ben-Baana instand." },
      { number: 5, text: "Die Männer von Tekoa* besserten das anschließende Stück aus. Doch die Vornehmen dieser Stadt weigerten sich mitzuarbeiten und gehorchten dem Statthalter nicht.", footnotes: ["Tekoa. Kleine Stadt 17 km südlich von Jerusalem, Heimat des Amos, siehe Amos 1,1."] },
      { number: 6, text: "Das Jeschana-Tor wurde von Jojada Ben-Paseach und Meschullam Ben-Besodja instand gesetzt. Sie setzten die Balken und die Torflügel ein und brachten Riegel und Sperrbalken an." },
      { number: 7, text: "Neben ihnen bauten Melatja aus Gibeon, Jadon aus Meronot und die Männer von Gibeon und Mizpa. In der Nähe dieses Teilstücks befand sich der Amtssitz des Statthalters der Westeuphrat-Provinz." },
      { number: 8, text: "Daneben arbeitete ein Goldschmied, Usiël Ben-Harhaja und neben ihm der Salbenmischer Hananja. Sie befestigten Jerusalem bis zur \"Breiten Mauer\"." },
      { number: 9, text: "Neben ihnen baute Refaja Ben-Hur, der Vorsteher des einen Halbbezirks von Jerusalem." },
      { number: 10, text: "Jedaja Ben-Harumaf setzte den anschließenden Teil gegenüber seinem eigenen Haus instand. Neben ihm baute Hattusch Ben-Haschabneja." },
      { number: 11, text: "Einen weiteren Abschnitt besserten Malkija Ben-Harim und Haschub Ben-Pahat-Moab aus, dazu den Ofenturm." },
      { number: 12, text: "Daneben baute Schallum Ben-Lohesch zusammen mit seinen Töchtern. Er war der Vorsteher des zweiten Halbbezirks von Jerusalem." },
      { number: 13, text: "Das Taltor besserten Hanun und die Bewohner von Sanoach aus. Sie setzten die Torflügel ein und brachten Riegel und Sperrbalken an. Außerdem besserten sie von dort noch 500 Meter Mauer bis zum Misttor aus." },
      { number: 14, text: "Das Misttor selbst baute Malkija Ben-Rechab wieder auf, der Vorsteher des Bezirks Bet-Kerem. Er setzte seine Torflügel ein und brachte Riegel und Sperrbalken an." },
      { number: 15, text: "Das Quelltor baute Schallun Ben-Kolhose wieder auf, der Vorsteher des Bezirks Mizpa. Er überdachte es, setzte seine Torflügel ein und brachte Riegel und Sperrbalken an. Außerdem baute er die Mauer am Teich der Wasserleitung beim königlichen Garten bis zu den Stufen, die von der Stadt Davids herabführen." },
      { number: 16, text: "Am nächsten Mauerabschnitt arbeitete Nehemja Ben-Asbuk, der Vorsteher des einen Halbbezirks von Bet-Zur. Dieser Teil der Mauer lag den Königsgräbern des Hauses David gegenüber und erstreckte sich bis zu dem künstlich angelegten Teich und dem Haus der Helden*.", footnotes: ["Haus der Helden. Eine in Jerusalem kasernierte Elitetruppe, ursprünglich Kampfgefährten von David."] },
      { number: 17, text: "Den nächsten Mauerabschnitt besserten die Leviten unter Rehum Ben-Bani aus und den folgenden Haschabja, der Vorsteher des ersten Halbbezirks von Keïla." },
      { number: 18, text: "Nach ihm arbeiteten Leviten unter Binnui Ben-Henadad, dem Vorsteher des zweiten Halbbezirks von Keïla." },
      { number: 19, text: "Neben ihm baute Eser Ben-Jeschua, der Vorsteher von Mizpa. Sein Abschnitt lag gegenüber dem Aufstieg zum Zeughaus am Winkel." },
      { number: 20, text: "Nach ihm besserte Baruch Ben-Sabbai mit großem Eifer den Mauerabschnitt zwischen dem Winkel und dem Eingang zum Haus des Hohen Priesters Eljaschib aus." },
      { number: 21, text: "Den nächsten Abschnitt bis zum Ende vom Haus des Eljaschib baute Meremot Ben-Urija, der Enkel von Koz." },
      { number: 22, text: "Neben ihm arbeiteten die Priester, die im Umkreis wohnten." },
      { number: 23, text: "Daneben setzten Benjamin und Haschub die Mauer gegenüber ihren Häusern instand und das anschließende Stück Asarja Ben-Aaseja. Es befand sich auch in der Nähe seines Hauses." },
      { number: 24, text: "Den nächsten Abschnitt vom Haus Asarjas bis zum Winkel und zur Ecke der Mauer baute Binnui Ben-Henadad." },
      { number: 25, text: "Palal Ben-Usai arbeitete an der Mauer gegenüber dem Winkel und dem oberen Turm, der am Königspalast beim Wachthof vorspringt. Pedaja Ben-Parosch" },
      { number: 26, text: "und die Tempelsklaven, die auf dem Ofel* wohnten, besserten den Teil vom Wassertor auf der Ostseite bis zum vorspringenden Turm aus.", footnotes: ["Ofel war der befestigte Hügel südlich vom Tempelberg, zwischen dem Tempel und der Davidsstadt."] },
      { number: 27, text: "Am nächsten Teil, vom vorspringenden Turm bis zur Mauer am Ofel, arbeiteten die Einwohner von Tekoa*.", footnotes: ["Einwohner von Tekoa. Sie bauten also zwei Mauerabschnitte wieder auf,fsiehe V. 5."] },
      { number: 28, text: "Den Abschnitt oberhalb des Rosstores setzten die Priester instand, jeder das Stück, das seinem Haus gegenüber lag." },
      { number: 29, text: "Auch Zadok Ben-Immer baute den Teil der Mauer wieder auf, der seinem Haus gegenüber lag." },
      { number: 30, text: "Den nächsten Teil bauten Hananja Ben-Schelemja und Hanun, der sechste Sohn Zalafs, wieder auf. Meschullam Ben-Berechja arbeitete an dem Abschnitt gegenüber seiner Wohnung." },
      { number: 31, text: "Nach ihm baute der Goldschmied Malkija die Mauer bis zum Haus der Tempelsklaven und Händler, gegenüber dem Wachttor, und bis zum oberen Raum an der Mauerecke." },
      { number: 32, text: "Den letzten Mauerabschnitt von dort bis zum Schaftor bauten die Goldschmiede und Händler wieder auf." },
      { number: 33, text: "Als Sanballat hörte, dass wir die Stadtmauer wieder aufbauten, wurde er wütend und ärgerte sich sehr. Er spottete über die Juden", heading: "Spott der Feinde" },
      { number: 34, text: "und sagte vor seinen Vertrauten und dem Heer von Samaria: \"Was machen diese elenden Juden da? Wollen sie einfach drauflos mauern? Wollen sie Opfer bringen und es an einem Tag schaffen? Wollen sie diese verbrannten Steine aus dem Schutt wieder zum Leben erwecken?\"" },
      { number: 35, text: "Der Ammoniter Tobija neben ihm sagte: \"Sie sollen nur bauen! Wenn ein Fuchs an ihre Mauer springt, wird er sie wieder einreißen.\"" },
      { number: 36, text: "Doch ich betete: \"Du, unser Gott, hör doch, wie sie über uns spotten! Lass ihren Spott auf sie selbst zurückfallen! Gib sie der Plünderung und der Gefangenschaft preis!" },
      { number: 37, text: "Deck ihre Schuld nicht zu! Lösch ihre Sünde vor dir nicht aus! Denn durch die Beleidigung der Bauenden wollten sie dich treffen!\"" },
      { number: 38, text: "Trotz allem bauten wir an der Mauer weiter, und schon bald war sie bis zur halben Höhe geschlossen, denn alle waren mit Eifer an der Arbeit." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Als Sanballat und Tobija, die Araber, die Ammoniter und die Leute von Aschdod erfuhren, dass der Wiederaufbau der Mauern Jerusalems Fortschritte machte, denn die Lücken schlossen sich allmählich, gerieten sie in Wut.", heading: "Störaktionen" },
      { number: 2, text: "Sie verbündeten sich, um bewaffnet gegen Jerusalem zu ziehen und dort Verwirrung zu stiften." },
      { number: 3, text: "Wir aber flehten zu unserem Gott und stellten Tag und Nacht Wachen gegen sie auf." },
      { number: 4, text: "Doch dann sagten die Juden: \"Die Kraft der Träger reicht nicht mehr, der Schutt ist viel zu viel! Wir schaffen es nicht mehr, an der Mauer zu bauen!\"" },
      { number: 5, text: "Unsere Feinde aber sagten sich: \"Sie sollen nichts merken und nichts von uns sehen, bis wir mitten unter ihnen sind. Dann schlagen wir sie tot und machen diesem Unternehmen ein Ende.\"" },
      { number: 6, text: "Und die Juden, die in ihrer Nähe wohnten, sagten uns vielleicht zehnmal: \"Wohin ihr euch auch dreht, überall sind sie gegen uns.\"" },
      { number: 7, text: "Da stellte ich alle wehrfähigen Männer an den offenen Stellen, wo die Mauer niedriger war als der Platz dahinter, nach Sippen geordnet und mit Schwertern, Speeren und Bogen bewaffnet auf." },
      { number: 8, text: "Nachdem ich mir alles angesehen hatte, sagte ich zu den führenden Männern, den Vorstehern und dem übrigen Volk: \"Habt keine Angst vor ihnen! Denkt vielmehr daran, wie groß und mächtig der Herr ist! Und kämpft für eure Brüder, eure Söhne und Töchter, eure Frauen und euren Besitz!\"" },
      { number: 9, text: "Als unsere Feinde hörten, dass wir gewarnt waren und Gott ihren Plan vereitelt hatte, konnten wir alle zu unseren Arbeitsplätzen an der Mauer zurückkehren." },
      { number: 10, text: "Doch von diesem Tag an arbeitete nur die Hälfte meiner Leute am Bau mit, während die andere Hälfte Wache hielt, mit Speeren und Schilden, Bogen und Schuppenpanzern ausgerüstet. Und die Oberen standen hinter den Leuten von Juda," },
      { number: 11, text: "die an der Mauer bauten. Die Lastträger arbeiteten so: Mit der einen Hand taten sie ihre Arbeit, mit der anderen hielten sie die Waffe." },
      { number: 12, text: "Alle Bauleute hatten während der Arbeit das Schwert am Gurt. Und ich hatte den Mann mit dem Schofar* immer bei mir.", footnotes: ["Der Schofar wurde aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 13, text: "Zu den Vornehmen, den Vorstehern und dem Volk hatte ich gesagt: \"Unsere Baustelle ist groß und weitläufig. Wir müssen uns über die ganze Mauer verteilen und sind dadurch weit voneinander entfernt." },
      { number: 14, text: "Wenn ihr von irgendeiner Stelle den Schofar hört, kommt sofort zu uns dorthin. Unser Gott wird für uns kämpfen.\"" },
      { number: 15, text: "So arbeiteten wir vom ersten Morgenrot an, bis die Sterne hervortraten. Die Hälfte der Männer hatte ständig den Speer in der Hand." },
      { number: 16, text: "Ich hatte befohlen, dass jeder mit seinen Leuten auch nachts in Jerusalem bleiben solle. So konnten sie uns nachts beim Wachdienst helfen und tagsüber an die Arbeit gehen." },
      { number: 17, text: "Weder ich noch einer von meinen Brüdern, weder meine Diener noch die Männer meiner Leibwache kamen in dieser Zeit aus den Kleidern. Selbst beim Waschen hatte jeder seine Waffe bei sich." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Auf einmal breitete sich eine große Unzufriedenheit bei den Männern des einfachen Volkes aus. Sie beschwerten sich mit ihren Frauen über ihre jüdischen Stammesbrüder.", heading: "Schuldenerlass für die Armen" },
      { number: 2, text: "Die einen klagten: \"Wir haben viele Söhne und Töchter und wissen nicht, wie wir satt werden sollen! Wir brauchen Getreide zum Überleben!\"" },
      { number: 3, text: "Andere sagten: \"Um in der Hungersnot Getreide zu bekommen, mussten wir unsere Felder, Weinberge und Häuser verpfänden.\"" },
      { number: 4, text: "Wieder andere beklagten sich: \"Und wir mussten unsere Felder und Weinberge verpfänden, um die Steuer für den König bezahlen zu können.\"" },
      { number: 5, text: "Und alle sagten: \"Wir sind doch vom gleichen Fleisch und Blut wie unsere Stammesbrüder! Sind unsere Kinder nicht genauso Israeliten wie ihre Kinder? Und doch müssen wir unsere Söhne und Töchter zu Sklaven erniedrigen. Einige unserer Töchter sind schon in ihrer Gewalt, und wir können nichts dagegen tun. Unsere Felder und Weinberge gehören ja anderen.\"" },
      { number: 6, text: "Als ich ihre Klage und diese Worte hörte, wurde ich sehr zornig." },
      { number: 7, text: "Ich dachte gründlich über alles nach und stellte dann die Vornehmen und Vorsteher zur Rede: \"Ihr nutzt die Not eurer Brüder schamlos aus!\" Dann brachte ich die Sache vor die ganze Volksversammlung." },
      { number: 8, text: "Ich sagte: \"Wir haben unsere jüdischen Stammesbrüder, die von Fremden zu Sklaven gemacht wurden, freigekauft, so weit es uns möglich war. Und ihr wollt sie jetzt selber verkaufen, damit sie dann wieder an uns verkauft werden?\" Da wussten sie keine Antwort und schwiegen." },
      { number: 9, text: "\"Es ist unwürdig, was ihr da tut!\", sagte ich. \"Solltet nicht gerade ihr in Furcht vor Gott leben? Doch so macht ihr uns zum Gespött für unsere Feinde!" },
      { number: 10, text: "Auch ich und meine Brüder und meine Diener haben Geld und Getreide verliehen. Erlassen wir ihnen doch die Rückzahlung!" },
      { number: 11, text: "Gebt ihnen unverzüglich ihre Felder und Weinberge, Olivenhaine und Häuser zurück!\"" },
      { number: 12, text: "Sie erwiderten: \"Gut, wir wollen alles zurückgeben und nichts mehr von ihnen fordern. Wir wollen alles tun, was du gesagt hast.\" Da rief ich die Priester und ließ die Gläubiger vor ihnen schwören, ihre Zusage wirklich zu halten." },
      { number: 13, text: "Außerdem schüttelte ich den Bausch meines Gewandes vor ihnen aus* und erklärte: \"Genauso soll Gott jeden, der diesen Schwur nicht hält, aus seinem Haus und Besitz herausschütteln. Ja, er selbst sei so ausgeschüttelt und geleert.\" Da rief die ganze Versammlung: \"Amen*!\" und lobte Jahwe. Alle hielten sich an diese Abmachung.", footnotes: ["schüttelte ... aus. Die vom Gürtel gebildete bauschige Falte des Gewandes, in der man kleinere Gegenstände und Tiere tragen konnte. Ihr Ausschütteln bezeugte die Ernsthaftigkeit des Schwurs.", "Amen. Hebräisch: Es werde wahr! Oder: So sei es!"] },
      { number: 14, text: "Ich selbst habe vom Anfang meiner Statthalterschaft in Juda an zwölf Jahre lang, vom 20. bis zum 32. Regierungsjahr* des Königs Artaxerxes, für mich und meine Brüder auf alle mir zustehenden Unterhaltskosten verzichtet.", heading: "Nehemias Uneigennützigkeit", footnotes: ["Das 32. Regierungsjahr des Artaxerxes dauerte vom 1. April 433 bis zum 19. April 432 v.Chr."] },
      { number: 15, text: "Frühere Statthalter hatten dem Volk schwere Lasten auferlegt und nicht nur Brot und Wein, sondern auch 40 Silberstücke* pro Tag von ihnen genommen. Auch ihre Diener hatten willkürlich über das Volk geherrscht. Ich habe das nicht so gemacht, weil ich Gott fürchtete.", footnotes: ["40 Silberstücke. Das war etwa ein halbes Kilogramm Silber."] },
      { number: 16, text: "Auch beim Bau der Mauer habe ich selbst Hand angelegt, und auch meine Leute haben mitgeholfen. Keiner von uns kaufte Land für sich selbst." },
      { number: 17, text: "An meinem Tisch speisten die 150 Vorsteher der Juden, dazu noch die Gäste von den umliegenden Völkern." },
      { number: 18, text: "Jeden Tag ließ ich ein Rind, sechs ausgesuchte Schafe und Geflügel zubereiten. Alle zehn Tage wurden die verschiedensten Weine in großer Menge angeliefert. Trotzdem habe ich auf die Unterhaltskosten, die mir als Statthalter zustanden, verzichtet, denn der Arbeitsdienst lastete schwer genug auf dem Volk." },
      { number: 19, text: "\"Denk an mich, mein Gott, und lass mir zugutekommen, was ich für dieses Volk getan habe!\"" },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Als Sanballat, Tobija, Geschem, der Araber, und unsere übrigen Feinde erfuhren, dass ich die Mauer fertig gebaut hatte, dass keine Lücke mehr geblieben war – nur die Torflügel hatte ich zu diesem Zeitpunkt noch nicht eingesetzt –,", heading: "Mordpläne gegen Nehemia" },
      { number: 2, text: "schickten Sanballat und Geschem einen Boten mit der Einladung zu mir, sie in Kefirim im Ono-Tal* zu treffen. Sie führten allerdings Böses gegen mich im Schilde.", footnotes: ["Kefirim im Ono-Tal. 11 km südöstlich von Joppe und 48 km von Jerusalem entfernt."] },
      { number: 3, text: "Ich ließ ihnen durch Boten ausrichten: \"Ich habe eine große Aufgabe zu bewältigen und kann nicht zu euch herunterkommen. Warum sollte die Arbeit dadurch ins Stocken geraten, dass ich mich mit euch treffe?\"" },
      { number: 4, text: "Viermal schickten sie mir die gleiche Einladung, und jedes Mal schickte ich ihnen dieselbe Antwort." },
      { number: 5, text: "Beim fünften Mal schickte mir Sanballat seinen Diener mit einem offenen Brief." },
      { number: 6, text: "Darin stand: \"Unter den Leuten geht ein Gerücht um – und Geschem bestätigt es auch –, dass du mit den Juden einen Aufstand vorbereitest und deshalb die Mauer wieder aufbaust. Man sagt, du wolltest ihr König werden." },
      { number: 7, text: "Du sollst sogar schon Propheten eingesetzt haben, die dich dann in Jerusalem zum König von Judäa ausrufen würden. Diese Gerüchte werden bestimmt auch dem König zu Ohren kommen. Komm also, damit wir beraten, was zu tun ist!\"" },
      { number: 8, text: "Ich ließ ihm ausrichten: \"Was du schreibst, ist völlig aus der Luft gegriffen. Das hast du alles frei erfunden.\"" },
      { number: 9, text: "So versuchten sie uns einzuschüchtern in der Hoffnung, dass wir die Arbeit abbrechen würden. Doch nun legte ich umso eifriger Hand ans Werk." },
      { number: 10, text: "Eines Tages besuchte ich Schemaja Ben-Delaja, den Enkel von Mehetabel, weil er verhindert war, zu mir zu kommen. Er sagte zu mir: \"Lass uns miteinander ins Haus Gottes gehen und uns im Innern des Tempels einschließen. Sie wollen dich nämlich umbringen – noch heute Nacht!\"" },
      { number: 11, text: "\"Ein Mann in meiner Stellung läuft nicht davon\", sagte ich. \"Und außerdem darf ich den Innenraum des Tempels überhaupt nicht betreten, denn das müsste ich mit dem Leben bezahlen. Nein, ich gehe nicht!\"" },
      { number: 12, text: "Mir war nämlich klar geworden, dass nicht Gott ihn geschickt hatte. Er hatte mir diese Prophezeiung nur gesagt, weil Tobija und Sanballat ihn dafür bezahlt hatten." },
      { number: 13, text: "Sie wollten ihn benutzen, um mir Angst einzujagen, und mich dadurch zu einer Sünde verleiten. Damit wollten sie mich in üblen Ruf bringen, um mich dann verächtlich machen zu können." },
      { number: 14, text: "\"Du, mein Gott, vergiss nicht, was Tobija und Sanballat getan haben. Denk auch daran, was die Prophetin Noadja und die anderen Propheten taten, um mich einzuschüchtern.\"" },
      { number: 15, text: "Die Mauer wurde in 52 Tagen am 25. September* fertiggestellt.", footnotes: ["September. Wörtlich: Elul (= 6. Monat). In knapp zwei Monaten wurde eine Mauer errichtet, die anderthalb Jahrhunderte in Schutt und Asche gelegen hatte."] },
      { number: 16, text: "Als unsere Feinde aus den Völkerschaften um uns herum davon hörten, fürchteten sie sich. Ihr Hochmut war ihnen vergangen, weil sie einsehen mussten, dass Gott dieses Werk vollbracht hatte." },
      { number: 17, text: "Während dieser ganzen Zeit standen einige der Vornehmen in Judäa in ständigem Briefwechsel mit Tobija." },
      { number: 18, text: "Denn viele Juden hatten ihm Beistand geschworen, weil er ein Schwiegersohn von Schechanja Ben-Arach war. Und Tobijas Sohn Johanan hatte eine Tochter von Meschullam Ben-Berechja geheiratet." },
      { number: 19, text: "Diese Leute rühmten Tobijas Verdienste vor mir und hinterbrachten ihm meine Worte. Daraufhin wollte Tobija mich mit seinen Briefen einschüchtern." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Als der Wiederaufbau der Mauer abgeschlossen war, ließ ich die Torflügel einsetzen. Dann wurden die Torwächter bestellt. Auch die Sänger und Leviten bekamen ihren Dienst zugewiesen.", heading: "Einsetzung der Wache" },
      { number: 2, text: "Zu Befehlshabern über Jerusalem ernannte ich meinen Bruder Hanani und den Burghauptmann Hananja, der ein zuverlässiger und gottesfürchtiger Mann war, wie es nicht viele gab." },
      { number: 3, text: "Ich sagte zu ihnen: \"Die Tore Jerusalems werden erst geöffnet, wenn die Sonne schon heiß scheint. Und abends, während sie noch am Himmel steht, werden die Tore geschlossen und verriegelt. Bildet einen Wachdienst aus den Einwohnern der Stadt. Ein Teil von ihnen soll an den besonders gefährdeten Stellen Wache stehen und die anderen bei ihrem Haus.\"" },
      { number: 4, text: "Nun war die Stadt ausgedehnt und groß, aber die Zahl der Einwohner klein; neugebaute Häuser waren nicht vorhanden.", heading: "Verzeichnis der Heimkehrer" },
      { number: 5, text: "Da gab es mir Gott in den Sinn, die Vornehmen, die Vorsteher und das ganze Volk zusammenzurufen, um sie nach ihren Sippen in Listen einzutragen. Dabei fand ich die Schriftrolle mit dem Verzeichnis der ersten Heimkehrer. Darin hieß es:" },
      { number: 6, text: "Die hier Eingetragenen der Provinz Judäa verließen Babylonien, wohin sie von König Nebukadnezzar verschleppt worden waren, und kehrten nach Jerusalem und Judäa in ihre Heimatorte zurück." },
      { number: 7, text: "Sie kamen mit Serubbabel, Jeschua, Nehemja, Asarja, Raamja, Nahamani, Mordochai, Bilschan, Misperet, Bigwai, Rehum und Baana.Es folgt ein Verzeichnis der heimgekehrten Sippen mit der Zahl der zu ihnen gehörenden Männer:" },
      { number: 8, text: "Parosch 2172," },
      { number: 9, text: "Schefatja 372," },
      { number: 10, text: "Arach 652," },
      { number: 11, text: "Pahat-Moab, die Nachkommen von Jeschua und Joab 2818," },
      { number: 12, text: "Elam 1254," },
      { number: 13, text: "Sattu 845," },
      { number: 14, text: "Sakkai 760," },
      { number: 15, text: "Bani 648," },
      { number: 16, text: "Bebai 628," },
      { number: 17, text: "Asgad 2322," },
      { number: 18, text: "Adonikam 667," },
      { number: 19, text: "Bigwai 2067," },
      { number: 20, text: "Adin 655," },
      { number: 21, text: "Ater, die Nachkommen von Hiskija 98," },
      { number: 22, text: "Haschum 328," },
      { number: 23, text: "Bezai 324," },
      { number: 24, text: "Harif 112," },
      { number: 25, text: "Gibeon 95," },
      { number: 26, text: "Netofa aus Bethlehem 188." },
      { number: 27, text: "Aus Anatot waren es 128," },
      { number: 28, text: "aus Bet-Asmawet 42," },
      { number: 29, text: "aus Kirjat-Jearim, Kefira und Beerot 743," },
      { number: 30, text: "aus Rama und Geba 621," },
      { number: 31, text: "aus Michmas 122," },
      { number: 32, text: "aus Bet-El und Ai 123," },
      { number: 33, text: "aus dem anderen Nebo 52." },
      { number: 34, text: "Von einem anderen Elam 1254," },
      { number: 35, text: "von Harim 320," },
      { number: 36, text: "aus Jericho 345," },
      { number: 37, text: "aus Lod, Hadid und Ono 721," },
      { number: 38, text: "von Senaa 3930." },
      { number: 39, text: "Von den Priestersippen kehrten zurück: Jedaja, die Nachkommen von Jeschua 973,", heading: "Heimgekehrte Priester und Leviten" },
      { number: 40, text: "Immer 1052," },
      { number: 41, text: "Paschhur 1247," },
      { number: 42, text: "Harim 1017." },
      { number: 43, text: "Von den Sippen der Leviten: Jeschua, die Nachkommen von Kadmiël, Binnui und Hodawja 74." },
      { number: 44, text: "Von den Tempelsängern: die Nachkommen Asafs 148." },
      { number: 45, text: "Von den Torwächtern des Tempels: die Sippen Schallum, Ater, Talmon, Akkub, Hatita und Schobai, 138 Mann." },
      { number: 46, text: "Von den Tempelsklaven kehrten folgende Sippen heim: Ziha, Hasufa, Tabbaot," },
      { number: 47, text: "Keros, Sia, Padon," },
      { number: 48, text: "Lebana, Hagaba, Salmai," },
      { number: 49, text: "Hanan, Giddel, Gahar," },
      { number: 50, text: "Reaja, Rezin, Nekoda," },
      { number: 51, text: "Gasam, Usa, Paseach," },
      { number: 52, text: "Besai, die Mëuniter, die Nefusiter," },
      { number: 53, text: "Bakbuk, Hakufa, Harhur," },
      { number: 54, text: "Bazlit, Mehida, Harscha," },
      { number: 55, text: "Barkos, Sisera, Temach," },
      { number: 56, text: "Neziach und Hatifa." },
      { number: 57, text: "Von den Sippen der Sklaven Salomos kehrten heim: Sotai, Soferet, Peruda," },
      { number: 58, text: "Jaala, Darkon, Giddel," },
      { number: 59, text: "Schefatja, Hattil, Pocheret-Zebajim und Amon." },
      { number: 60, text: "Die Gesamtzahl der Tempelsklaven und der Nachkommen der Sklaven Salomos betrug 392." },
      { number: 61, text: "Aus Tel-Melach, Tel-Harscha, Kerub-Addon und Immer kamen folgende Sippen, die ihre Herkunft aus Israel nicht nachweisen konnten:" },
      { number: 62, text: "Delaja, Tobija und Nekoda 642." },
      { number: 63, text: "Die Priestersippen Habaja, Koz und Barsillai. Barsillai hatte damals eine Tochter von dem Barsillai aus Gilead geheiratet und dessen Namen angenommen." },
      { number: 64, text: "Sie konnten ihre Abstammungsnachweise nicht finden. Deshalb wurden sie für unrein erklärt und vom Priesteramt ausgeschlossen." },
      { number: 65, text: "Der Statthalter untersagte ihnen, von den höchst heiligen Opfergaben zu essen, bis wieder ein Priester für die Urim und Tummim* auftreten würde.", footnotes: ["Urim und Tummim. Die heiligen Lose, die in der Brusttasche des hohenpriesterlichen Gewandes aufbewahrt wurden, siehe 2. Mose 28,30."] },
      { number: 66, text: "Die ganze Versammlung zählte 42.360 Personen*,", heading: "Gesamtzahl von Personen und Spenden", footnotes: ["42360 Personen. Die Zahl ist höher als die Summe der einzelnen Angaben. Es könnte aber sein, dass nur die Nachkommen aus den Stämmen Juda und Benjamin gesondert aufgezählt sind und die Differenzsumme Menschen aus den anderen Stämmen betraf."] },
      { number: 67, text: "dazu kamen 7337 Sklaven und Sklavinnen und 245 Sänger und Sängerinnen.*", footnotes: ["Sängerinnen. Einige hebräische Handschriften und die LXX haben hier aus Esra 2,66 eingefügt: \"Außerdem brachten die Israeliten 736 Pferde, 245 Maultiere.\""] },
      { number: 68, text: "Sie hatten 435 Kamele und 6720 Esel." },
      { number: 69, text: "Einige von den Sippenoberhäuptern gaben Spenden für das Werk. Der Statthalter spendete achteinhalb Kilogramm Goldstücke*, 50 Opferschalen und 530 Priestergewänder.", footnotes: ["... Goldstücke. Wörtlich: 1000 Golddariken. Eine Darike wog etwa 8,4 Gramm."] },
      { number: 70, text: "Einige Sippenoberhäupter spendeten für den Bau 170 Kilogramm Goldstücke und 1250 Kilogramm Silber*.", footnotes: ["1250 Kilogramm Silber. Wörtlich: 2200 Minen.Eine Mine wog 558-610 Gramm."] },
      { number: 71, text: "Das übrige Volk spendete 170 Kilogramm Goldstücke, 1140 Kilogramm Silber und 67 Priestergewänder." },
      { number: 72, text: "Die Priester, die Leviten, die Torwächter, die Sänger, die Tempelsklaven und das übrige Volk ließen sich in ihren Heimatorten nieder.Als der Oktober* herankam und die Israeliten in ihren Städten wohnten,", footnotes: ["Oktober. Wörtlich: des 7. Monats."] },
    ] },
    { number: 8, verses: [
      { number: 1, text: "versammelte sich das ganze Volk auf dem Platz vor dem Wassertor. Sie baten den Gesetzeslehrer Esra, das Buch mit dem Gesetz Moses herbeizubringen, dem Gesetz, das Jahwe den Israeliten verordnet hat.", heading: "8-10: Wiederherstellung des Bundes mit Gott\nDie Feste werden gefeiert" },
      { number: 2, text: "Da brachte der Priester Esra das Gesetzbuch vor die ganze Versammlung, vor die Männer und Frauen und alle Kinder, die es schon verstehen konnten. Am 1. Oktober*", footnotes: ["Am 8. Oktober. Wörtlich:Am 1. des 7. Monats. Das war der Neujahrstag des zivilen Jahres 445 v.Chr."] },
      { number: 3, text: "las er vom frühen Morgen bis zum Mittag auf dem Platz vor dem Wassertor aus dem Gesetzbuch vor. Das ganze Volk hörte aufmerksam auf die Worte des Buches." },
      { number: 4, text: "Der Schriftgelehrte Esra stand dabei auf einem hölzernen Podest, das man zu diesem Zweck errichtet hatte. Rechts neben ihm standen Mattitja, Schema, Anaja, Urija, Hilkija und Maaseja, und links neben ihm Pedaja, Mischaël, Malkija, Haschum, Haschbaddana, Secharja und Meschullam." },
      { number: 5, text: "Esra öffnete die Schriftrolle vor aller Augen, denn er stand höher als das versammelte Volk." },
      { number: 6, text: "Zuerst pries Esra Jahwe, den großen Gott, und alle antworteten mit erhobenen Händen: \"Amen, Amen!\" Dann warfen sie sich vor Jahwe nieder, mit dem Gesicht auf den Boden." },
      { number: 7, text: "Die Leviten Jeschua, Bani, Scherebja, Jamin, Akkub, Schabbetai, Hodija, Maaseja, Kelita, Asarja, Josabad, Hanan und Pelaja halfen den Leuten, das Gelesene zu verstehen, wobei das Volk auf seinem Platz blieb." },
      { number: 8, text: "Sie übersetzten die vorgelesenen Abschnitte* und erklärten die Weisung Gottes, damit das Volk sie verstehen konnte.", footnotes: ["übersetzten ... Abschnitte. Seit der babylonischen Gefangenschaft war Aramäisch (Syrisch) die Umgangssprache in Israel und die hebräischen Texte der Heiligen Schrift mussten für das Volk übersetzt werden."] },
      { number: 9, text: "Als die Israeliten die Worte des Gesetzes vernahmen, fingen sie an zu weinen. Da sagten der Statthalter Nehemia, der Priester und Gesetzeslehrer Esra und die Leviten, die das Volk unterwiesen: \"Seid nicht traurig und weint nicht, denn dieser Tag ist Jahwe, eurem Gott, geweiht!" },
      { number: 10, text: "Geht jetzt zu eurem Festmahl, esst und trinkt und gebt auch denen etwas ab, für die nichts vorbereitet ist! Heute ist ein Festtag für Jahwe. Seid nicht traurig, denn die Freude an Jahwe ist euer Schutz!\"" },
      { number: 11, text: "Auch die Leviten redeten dem Volk gut zu: \"Beruhigt euch, denn der Tag ist heilig! Ihr müsst nicht traurig sein!\"" },
      { number: 12, text: "Da gingen alle zum Essen und Trinken und teilten ihr Festmahl mit denen, die nichts hatten. Sie feierten ein großes Freudenfest, denn sie hatten die Worte verstanden, die ihnen übermittelt worden waren." },
      { number: 13, text: "Am nächsten Tag kamen die Sippenoberhäupter des ganzen Volkes mit den Priestern und Leviten zu Esra, dem Schriftgelehrten, um die Aussagen des Gesetzes noch besser zu verstehen.", heading: "Das Laubhüttenfest" },
      { number: 14, text: "Da entdeckten sie im Gesetz, das Jahwe durch Mose angeordnet hatte, dass die Israeliten während dieses Festes im Oktober* in Laubhütten wohnen sollten.", footnotes: ["Oktober. Wörtlich: im 7. Monat. – Zum Laubhüttenfest siehe 3. Mose 23,33-44."] },
      { number: 15, text: "Da ließen sie in Jerusalem und in allen Städten ausrufen: \"Geht auf die umliegenden Berge und holt frische Zweige von edlen und wilden Ölbäumen, von Myrten, von Palmen und anderen dichtbelaubten Bäumen, um Laubhütten zu bauen, wie es das Gesetz vorschreibt!\"" },
      { number: 16, text: "Das Volk gehorchte und brachte Zweige und baute sich Laubhütten – die einen auf ihren Dachterrassen, die anderen in ihren Höfen, in den Vorhöfen des Tempels oder auf dem Platz vor dem Wassertor oder beim Efraïmtor." },
      { number: 17, text: "Die ganze Versammlung der Heimkehrer baute Laubhütten und wohnte darin. Das hatten die Israeliten seit der Zeit von Josua Ben-Nun bis zu diesem Tag nicht mehr getan. Und alle freuten sich sehr." },
      { number: 18, text: "An jedem der sieben Festtage wurde aus dem Buch des göttlichen Gesetzes vorgelesen. Am achten Tag fand die vorgeschriebene Festversammlung statt." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Am 24. Oktober* kamen die Israeliten zu einem Fastentag zusammen. Sie hatten den Trauersack angezogen und sich Erde auf den Kopf gestreut.", heading: "Das Bußgebet des Volkes", footnotes: ["Oktober. Wörtlich: dieses Monats."] },
      { number: 2, text: "Sie hatten sich von all denen getrennt, die ihrer Abstammung nach keine Israeliten waren, und versammelten sich nun, um ihre Sünden und die Verfehlungen ihrer Väter zu bekennen." },
      { number: 3, text: "Sie erhoben sich von ihren Plätzen, und drei Stunden* lang wurde ihnen aus dem Buch des Gesetzes Jahwes, ihres Gottes, vorgelesen. Dann warfen sie sich vor Jahwe nieder und bekannten ihm drei Stunden lang ihre Verfehlungen.", footnotes: ["drei Stunden. Wörtlich:ein Viertel des Tages."] },
      { number: 4, text: "Auf dem Podest der Leviten standen Jeschua, Bani, Kadmiël, Schebanja, Bunni, Scherebja, Bani und Kenani. Sie schrien mit lauter Stimme um Hilfe zu Jahwe, ihrem Gott." },
      { number: 5, text: "Dann riefen die Leviten Jeschua, Kadmiël, Bani, Haschabneja, Scherebja, Hodija, Schebanja und Petachja dem Volk zu: \"Steht auf und preist Jahwe, euren Gott von Ewigkeit zu Ewigkeit!\"Und sie beteten: \"Man preise deinen herrlichen Namen, Jahwe! Er ist größer als alles Preisen und Rühmen es ausdrücken kann." },
      { number: 6, text: "Du, Jahwe, bist der einzige Gott. Du hast alle Himmel gemacht, die ganze Himmelswelt und alle Heerscharen darin, die Erde und alles, was auf ihr lebt, die Meere und alles, was in ihnen ist. Ihnen allen hast du das Leben geschenkt, und das Heer des Himmels betet dich an." },
      { number: 7, text: "Du, o Jahwe, bist der Gott, der Abram erwählte. Du holtest ihn aus Ur in Chaldäa heraus und gabst ihm den Namen Abraham." },
      { number: 8, text: "Und als du sahst, dass er treu zu dir hielt, hast du den Bund mit ihm geschlossen und ihm versprochen, seinen Nachkommen das Land der Kanaaniter, der Hetiter, Amoriter, Perisiter, Jebusiter und Girgaschiter zu geben. Und du hast dein Versprechen gehalten, denn du bist gerecht!" },
      { number: 9, text: "Du sahst die Bedrückung unserer Väter in Ägypten und hast ihren Hilfeschrei am Schilfmeer gehört." },
      { number: 10, text: "Dem Pharao hast du deine Wunderzeichen gezeigt und ihm deine Macht zu spüren gegeben, seinen Ministern und seinem ganzen Volk, denn du hast gesehen, wie hochmütig sie unsere Väter behandelten. Und so hast du dir bis heute einen Namen gemacht." },
      { number: 11, text: "Vor ihren Augen hast du das Meer gespalten, sodass unsere Väter trockenen Fußes mitten hindurchziehen konnten. Doch ihre Verfolger hast du in den Strudel geschleudert, wie einen Stein in tosende Fluten." },
      { number: 12, text: "Am Tag hast du sie durch eine Wolkensäule geführt und in der Nacht ihren Weg durch eine Feuersäule erhellt." },
      { number: 13, text: "Auf den Sinai bist du herabgestiegen und hast vom Himmel her mit ihnen geredet. Klare Ordnungen hast du ihnen gegeben, Gesetze, auf die man sich verlassen kann, gute Vorschriften und Gebote." },
      { number: 14, text: "Du lehrtest sie den Sabbat zu halten als heiligen Tag und gabst ihnen durch deinen Diener Mose Gebote, Ordnungen und ein Gesetz." },
      { number: 15, text: "Für ihren Hunger gabst du ihnen Brot vom Himmel und für ihren Durst Wasser aus dem Fels. Und dann befahlst du ihnen, das Land einzunehmen, das du ihnen versprochen hattest mit zum Schwur erhobener Hand." },
      { number: 16, text: "Doch unsere Väter wurden hochmütig. Trotzig schlugen sie deine Weisungen in den Wind!" },
      { number: 17, text: "Sie wollten dir nicht gehorchen und dachten nicht mehr an die großen Wunder, mit denen du ihnen geholfen hattest. Stur wie sie waren, wollten sie einen Anführer wählen und zurück in die ägyptische Sklaverei. Doch du bist ein Gott, der Vergebung schenkt, bist gnädig und voller Erbarmen. Du hast große Geduld und unendliche Gnade und ließest sie nicht im Stich." },
      { number: 18, text: "Selbst als sie sich ein Stierkalb machten und sagten: 'Das ist dein Gott, der dich aus Ägypten geführt hat!' und dich damit tief verletzten," },
      { number: 19, text: "hast du sie dort in der Wüste nicht verlassen. Du nahmst die Wolkensäule nicht weg, die sie führte, und auch die Feuersäule nicht, die nachts ihren Weg erhellte." },
      { number: 20, text: "Deinen guten Geist hast du ihnen geschenkt, um sie zur Einsicht zu bringen. Dein Manna enthieltest du ihnen nicht vor und gabst ihnen Wasser für ihren Durst." },
      { number: 21, text: "Vierzig Jahre lang hast du sie in der Wüste versorgt. Sie hatten alles, was sie brauchten. Ihre Kleidung nutzte sich nicht ab und ihre Füße schwollen nicht an." },
      { number: 22, text: "Ganze Königreiche und Völker gabst du in ihre Gewalt, ein Land nach dem anderen eroberten sie. So nahmen sie das Land des Königs Sihon von Heschbon in Besitz, und das Land des Königs Og von Baschan." },
      { number: 23, text: "Du hast ihre Nachkommen so zahlreich wie die Sterne am Himmel gemacht und sie in das Land gebracht, das nach deinem Willen schon die Väter in Besitz nehmen sollten." },
      { number: 24, text: "Nun zogen sie hinein und eroberten es. Die Bewohner Kanaans gabst du in ihre Gewalt, ihre Herrscher und ihre Völker, und sie konnten mit ihnen machen, was sie wollten." },
      { number: 25, text: "Befestigte Städte nahmen sie ein und fruchtbares Land, Häuser mit Gütern gefüllt und fertige Zisternen, Weinberge und Olivenhaine und Obstbäume in großer Zahl. Es ging ihnen gut, sie aßen sich satt und genossen die Fülle deiner guten Gaben." },
      { number: 26, text: "Aber dann wurden sie trotzig und empörten sich gegen dich, sie schleuderten deine Weisungen hinter sich. Sie brachten deine Propheten um, die sie warnten, um sie zu dir zurückzubringen. So kränkten sie dich sehr." },
      { number: 27, text: "Da gabst du sie der Gewalt ihrer Feinde preis und diese bedrängten sie hart. Dann schrien sie zu dir, und du erhörtest sie vom Himmel her. In deinem Erbarmen schicktest du ihnen Retter und hast sie von ihren Peinigern erlöst." },
      { number: 28, text: "Doch kaum hattest du ihnen Ruhe verschafft, lehnten sie sich erneut gegen dich auf. Da überließest du sie wieder den Händen ihrer Feinde, und die herrschten hart über sie. Wieder schrien sie zu dir und du erhörtest sie vom Himmel her. Immer wieder hast du sie in deinem Erbarmen befreit." },
      { number: 29, text: "Obwohl du sie ernstlich gewarnt hast, um sie zu deinem Gesetz zurückzuführen, trotzten sie dir und gehorchten deinen Geboten nicht. Sie sündigten gegen deine Ordnungen, durch die der Mensch doch lebt, wenn er sie tut. Sie zeigten dir die kalte Schulter, boten dir trotzig die Stirn und gehorchten dir nicht." },
      { number: 30, text: "Viele Jahre hattest du mit ihnen Geduld und warntest sie durch deinen Geist, der deinen Propheten die Worte gab. Aber sie hörten nicht hin. Da gabst du sie in die Gewalt fremder Völker." },
      { number: 31, text: "Doch weil du sehr barmherzig bist, hast du sie nicht beseitigt und sie nicht verlassen. Denn du bist gnädig und voller Erbarmen." },
      { number: 32, text: "Und nun, unser Gott, du großer, starker und furchtbarer Gott, der sich seine Gnade bewahrt und zu seinem Bund steht! Lass doch all das Leid, das uns betroffen hat, unsere Könige und Führer, unsere Priester und Propheten, unsere Vorfahren und dein ganzes Volk seit der Herrschaft der assyrischen Könige bis heute, lass doch all das Leid dir nicht gering erscheinen." },
      { number: 33, text: "Du warst im Recht, wenn uns das alles getroffen hat, denn du bist treu geblieben; doch wir, wir haben uns schuldig gemacht." },
      { number: 34, text: "Ja, unsere Könige, unsere Vorsteher und Priester, unsere Vorfahren haben dein Gesetz nicht befolgt, auf deine Gebote nicht geachtet und deine Warnungen in den Wind geschlagen." },
      { number: 35, text: "Du hattest ihnen die Herrschaft anvertraut, du hattest sie mit Gütern reich beschenkt und ihnen ein weites, fruchtbares Land gegeben. Doch sie haben dir nicht gedient und kehrten von ihrem bösen Treiben nicht um." },
      { number: 36, text: "Und heute sind wir Sklaven in dem Land, das du unseren Vorfahren anvertraut hast, damit sie seine Früchte und seinen Reichtum genießen. Ja, wir sind hier Sklaven geworden," },
      { number: 37, text: "und der Ertrag unseres Landes kommt den Königen zugute, die du über uns gesetzt hast. Sie haben Gewalt über unsere Körper und unser Vieh; sie behandeln uns, wie es ihnen gerade gefällt, und wir sind in großer Not.\"" },
    ] },
    { number: 10, verses: [
      { number: 1, text: "\"Und wegen all dem verpflichten wir uns nun schriftlich. Auf der gesiegelten Schrift sollen die Namen unserer Vorsteher, unserer Leviten und Priester stehen.\"", heading: "Verpflichtung auf das Gesetz" },
      { number: 2, text: "Als erster unterzeichnete der Statthalter Nehemia Ben-Hachalja, dann die Priester Zidkija," },
      { number: 3, text: "Seraja, Asarja, Jirmeja," },
      { number: 4, text: "Paschhur, Amarja, Malkija," },
      { number: 5, text: "Hattusch, Schebanja, Malluch," },
      { number: 6, text: "Harim, Meremot, Obadja," },
      { number: 7, text: "Daniel, Ginneton, Baruch," },
      { number: 8, text: "Meschullam, Abija, Mijamin," },
      { number: 9, text: "Maasja, Bilga und Schemaja." },
      { number: 10, text: "Dann unterschrieben die Leviten Jeschua Ben-Asanja, Binnui aus der Sippe Henadad sowie Kadmiël," },
      { number: 11, text: "ferner ihre Brüder Schebanja, Hodija, Kelita, Pelaja, Hanan," },
      { number: 12, text: "Micha, Rehob, Haschabja," },
      { number: 13, text: "Sakkur, Scherebja, Schebanja," },
      { number: 14, text: "Hodija, Bani und Beninu." },
      { number: 15, text: "Schließlich unterzeichneten die Vorsteher Parosch, Pahat-Moab, Elam, Sattu, Bani," },
      { number: 16, text: "Bunni, Asgad, Bebai," },
      { number: 17, text: "Adonija, Bigwai, Adin," },
      { number: 18, text: "Ater, Hiskija, Asur," },
      { number: 19, text: "Hodija, Haschum, Bezai," },
      { number: 20, text: "Harif, Anatot, Nebai," },
      { number: 21, text: "Magpiasch, Meschullam, Hesir," },
      { number: 22, text: "Meschesabel, Zadok, Jaddua," },
      { number: 23, text: "Pelatja, Hanan, Anaja," },
      { number: 24, text: "Hoschea, Hananja, Haschub," },
      { number: 25, text: "Lohesch, Pilha, Schobek," },
      { number: 26, text: "Rehum, Haschabna, Maaseja," },
      { number: 27, text: "Ahija, Hanan, Anan," },
      { number: 28, text: "Malluch, Harim und Baana." },
      { number: 29, text: "Auch das übrige Volk schloss sich der Verpflichtung an: die restlichen Priester und Leviten, die Torwächter, Sänger und Tempelsklaven, und alle, die sich von den nichtisraelitischen Völkern im Land getrennt hatten, um das Gesetz Gottes zu befolgen, dazu ihre Frauen und alle von ihren Söhnen und Töchtern, die alt genug waren, die Vereinbarung zu verstehen." },
      { number: 30, text: "Zusammen mit ihren Vorstehern legten sie einen Eid ab, das Gesetz, das Gott uns durch Mose, seinen Diener, gegeben hat, und alle Gebote, Vorschriften und Anweisungen Jahwes, unseres Herrn, zu befolgen." },
      { number: 31, text: "\"Wir verpflichten uns, unsere Töchter nicht in fremde Volksgruppen im Land zu verheiraten und von ihnen keine Frauen für unsere Söhne zu nehmen." },
      { number: 32, text: "Und wenn diese Fremden ihr Getreide oder andere Waren am Sabbat oder einem anderen heiligen Tag zum Verkauf bringen, wollen wir ihnen nichts abkaufen. Jedes siebte Jahr lassen wir das Land brach liegen und erlassen alle Schulden." },
      { number: 33, text: "Wir verpflichten uns, jährlich einen Drittelschekel* für den Dienst im Tempel unseres Gottes zu geben,", footnotes: ["Drittelschekel. Silbermünze, etwa 4 Gramm."] },
      { number: 34, text: "für die geweihten Brote, für die täglichen Speis- und Brandopfer, für die Opfer am Sabbat, am Neumondsfest und an den übrigen Festtagen, für die geweihten Gaben und die Sündopfer, die Israels Schuld tilgen, sowie für alle Arbeiten am Haus unseres Gottes." },
      { number: 35, text: "Die Lieferung des Brennholzes für die im Gesetz vorgeschriebenen Opfer auf dem Altar Jahwes, unseres Gottes, losen wir zusammen mit den Priestern und Leviten jährlich aus und bestimmen so, welche Sippen es zu den festgesetzten Zeiten liefern müssen." },
      { number: 36, text: "Jedes Jahr werden wir die ersten Früchte von unseren Feldern und Fruchtbäumen zum Haus Jahwes bringen." },
      { number: 37, text: "Wie es im Gesetz vorgeschrieben ist, werden wir auch unsere erstgeborenen Söhne* sowie die Erstgeburten von unseren Rindern und Schafen zu den diensttuenden Priestern im Haus unseres Gottes bringen.", footnotes: ["erstgeborenen Söhne. Alle Erstgeburt gehörte Gott. Menschen wurden jedoch in den Tempel gebracht und dort ausgelöst (siehe 2. Mose 13,2; 4. Mose 18,16-18)."] },
      { number: 38, text: "In den Vorratsräumen des Tempels werden wir ihnen auch den Brotteig aus dem ersten Getreide des Jahres abliefern sowie die besten Früchte unserer Bäume, den ersten Wein und das erste Olivenöl. Den Leviten geben wir den Zehnten vom Ertrag unserer Felder, denn sie erheben den Zehnten an allen Orten, wo wir Ackerbau betreiben." },
      { number: 39, text: "Wenn die Leviten den Zehnten in Empfang nehmen, soll ein Priester, ein Nachkomme Aarons, in ihrer Begleitung sein. Den Zehnten vom Zehnten sollen die Leviten nämlich an den Tempel abliefern und in die Vorratskammern dort bringen." },
      { number: 40, text: "In diese Räume sollen die Israeliten und die Leviten das Getreide, den Wein und das Olivenöl abliefern. Dort werden die Gegenstände für den Tempeldienst aufbewahrt, und dort halten sich auch die diensttuenden Priester, die Torwächter und Sänger auf. Wir wollen das Haus unseres Gottes nicht vernachlässigen.\"" },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Die Führer des Volkes wohnten schon in Jerusalem. Aus der übrigen Bevölkerung wurde jede zehnte Familie durch das Los dazu bestimmt, ebenfalls in Jerusalem, der heiligen Stadt, zu wohnen. Die anderen Familien konnten in ihren Ortschaften bleiben.", heading: "11-13: Wiederbesiedlung der Stadt Jerusalem\nDie Einwohner von Jerusalem" },
      { number: 2, text: "Und jede Familie, die freiwillig nach Jerusalem zog, wurde vom Volk gesegnet." },
      { number: 3, text: "Die folgende Liste verzeichnet die Sippenoberhäupter der Provinz Judäa, die in Jerusalem wohnten. Die übrigen Israeliten, die Priester, die Leviten, die Tempelsklaven und die Nachkommen der Sklaven Salomos wohnten in den Städten Judäas, jeder auf seinem Erbbesitz." },
      { number: 4, text: "Aus dem Stamm Juda wohnten in Jerusalem: Ataja Ben-Usija; er stammte über Secharja, Amarja, Schefatja und Mahalalel von Judas Sohn Perez ab." },
      { number: 5, text: "Maaseja Ben-Baruch; er stammte über Kolhose, Hasaja, Adaja, Jojarib und Secharja von Schela ab." },
      { number: 6, text: "Von den Nachkommen des Perez wohnten 468 angesehene Männer in Jerusalem." },
      { number: 7, text: "Aus dem Stamm Benjamin: Sallu Ben-Meschullam, der von Joëd, Pedaja, Kolaja, Maaseja, Itiël und Jeschaja abstammte," },
      { number: 8, text: "und seine Brüder Gabbai und Sallai, 928." },
      { number: 9, text: "Joël Ben-Sichri war ihr Vorgesetzter und Juda Ben-Senua der zweite Stadtvorsteher." },
      { number: 10, text: "Von den Priestern: Jedaja Ben-Jojarib, sowie Jachin." },
      { number: 11, text: "Seraja Ben-Hilkija, der von Meschullam, Zadok, Merajot und Ahitub abstammte, war Vorsteher im Haus Gottes." },
      { number: 12, text: "Es waren 822 ihrer Männer, die den Dienst im Tempel verrichteten. Dann Adaja Ben-Jeroham, der von Pelalja, Amzi, Secharja, Paschhur und Malkija abstammte." },
      { number: 13, text: "Seine Sippe umfasste 242 Familienoberhäupter. Dann Amaschsai Ben-Asarel, der von Achsai, Meschillemot und Immer abstammte." },
      { number: 14, text: "Seine Sippe umfasste 128 Familien. Ihr Anführer war Sabdiël Ben-Haggedolim." },
      { number: 15, text: "Von den Leviten: Schemaja Ben-Haschub, der von Asrikam, Haschabja und Bunni abstammte." },
      { number: 16, text: "Außerdem Schabbetai und Josabad, Sippenoberhäupter, die für den Dienst im äußeren Bereich des Tempels verantwortlich waren." },
      { number: 17, text: "Mattanja Ben-Micha, der von Sabdi und Asaf abstammte, leitete den Lobgesang und stimmte den Lobpreis beim Gebet an; Bakbukja, einer seiner Verwandten, war sein Stellvertreter, ebenso Abda Ben-Schammua, der von Galal und Jedutun abstammte." },
      { number: 18, text: "Insgesamt wohnten 284 Levitenfamilien in der Heiligen Stadt." },
      { number: 19, text: "Torwächter: Akkub, Talmon und ihre Verwandten, insgesamt 172." },
      { number: 20, text: "Die übrigen Israeliten, einschließlich der Priester und Leviten, wohnten in allen Orten Judas zerstreut, jeder auf seinem Erbbesitz." },
      { number: 21, text: "Die Tempelsklaven wohnten auf dem Ofel. Sie arbeiteten unter der Aufsicht von Ziha und Gischpa." },
      { number: 22, text: "Vorsteher der Leviten in Jerusalem war Usi Ben-Bani, der von Haschabja, Mattanja und Micha abstammte. Er gehörte zu den Nachkommen Asafs, die beim Gottesdienst im Tempel für den Gesang zuständig waren." },
      { number: 23, text: "Eine Anordnung des Königs* regelte ihren Dienst für jeden Tag.", footnotes: ["Anordnung des Königs. Schon Darius I. hatte dafür Anordnungen gegeben, siehe Esra 6,10, offenbar auch Artaxerxes."] },
      { number: 24, text: "Petachja Ben-Meschesabel, der von Serach Ben-Juda abstammte, beriet den König in allen Angelegenheiten des Volkes." },
      { number: 25, text: "Was die Gehöfte auf dem Land betrifft, wohnten einige Juden in Kirjat-Arba und Dibon mit den dazugehörigen Dörfern; und in Kabzeel mit den dazugehörigen Gehöften;", heading: "Landbewohner" },
      { number: 26, text: "außerdem in Jeschua, Molada, Bet-Pelet," },
      { number: 27, text: "Hazar-Schual, Beerscheba und seinen Dörfern," },
      { number: 28, text: "Ziklag, Mechona und seinen Dörfern," },
      { number: 29, text: "En-Rimmon, Zora, Jarmut;" },
      { number: 30, text: "in Sanoach und Adullam und den dazugehörigen Gehöften, Lachisch und dem dazugehörigen Gebiet sowie Aseka und seinen Dörfern. Ihr Gebiet reichte von Beerscheba bis zum Hinnom-Tal." },
      { number: 31, text: "Benjaminiten wohnten auch in Geba, Michmas, Aja, Bet-El und seinen Dörfern," },
      { number: 32, text: "Anatot, Nob, Ananeja," },
      { number: 33, text: "Hazor, Rama, Gittajim," },
      { number: 34, text: "Hadid, Zeboim, Neballat," },
      { number: 35, text: "Lod, Ono und dem Tal der Handwerker." },
      { number: 36, text: "Einige Gruppen von Leviten wohnten in Juda, andere ließen sich im Gebiet von Benjamin nieder." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Folgende Priester und Leviten waren mit Serubbabel Ben-Schealtiël und Jeschua aus der Verbannung heimgekehrt: Seraja, Jirmeja, Esra,", heading: "Priester und Leviten" },
      { number: 2, text: "Amarja, Malluch, Hattusch," },
      { number: 3, text: "Schechanja, Harim, Meremot," },
      { number: 4, text: "Iddo, Ginneton, Abija," },
      { number: 5, text: "Mijamin, Maadja, Bilga," },
      { number: 6, text: "Schemaja, Jojarib, Jedaja," },
      { number: 7, text: "Sallu, Amok, Hilkija und Jedaja. Dies waren die Oberhäupter der Priester und ihre Brüder in der Zeit des Hohen Priesters Jeschua." },
      { number: 8, text: "Die Leviten Jeschua, Binnui, Kadmiël, Scherebja, Juda und Mattanja waren für den Gesang zuständig." },
      { number: 9, text: "Bakbukja, Unni und ihre Brüder standen ihnen nach Dienstabteilungen gegenüber." },
      { number: 10, text: "Der Hohe Priester Jeschua zeugte Jojakim, Jojakim Eljaschib, Eljaschib Jojada," },
      { number: 11, text: "Jojada zeugte Jonatan, Jonatan Jaddua." },
      { number: 12, text: "Zur Zeit Jojakims waren folgende Priester die Oberhäupter ihrer Sippen. Für Seraja: Meraja; für Jirmeja: Hananja;" },
      { number: 13, text: "für Esra: Meschullam; für Amarja: Johanan" },
      { number: 14, text: "für Malluch: Jonatan; für Schebanja: Josef;" },
      { number: 15, text: "für Harim: Adna; für Merajot: Helkai;" },
      { number: 16, text: "für Iddo: Secharja; für Ginneton: Meschullam;" },
      { number: 17, text: "für Abija: Sichri; für Mijamin ...; für Maadja: Piltai;" },
      { number: 18, text: "für Bilga: Schammua; für Schemaja: Jonatan;" },
      { number: 19, text: "für Jojarib: Mattenai; für Jedaja: Usi;" },
      { number: 20, text: "für Sallai: Kallai; für Amok: Eber;" },
      { number: 21, text: "für Hilkija: Haschabja; für Jedaja: Netanel." },
      { number: 22, text: "Zur Zeit der Hohen Priester Eljaschib, Jojada, Johanan und Jaddua sowie des Perserkönigs Darius wurden Verzeichnisse angelegt, in denen die Sippenoberhäupter der Leviten und Priester erfasst waren." },
      { number: 23, text: "Von den Leviten wurden die Sippenoberhäupter bis zur Amtszeit von Johanan Ben-Eljaschib in der amtlichen Chronik erfasst." },
      { number: 24, text: "Es waren: Haschabja, Scherebja und Jeschua Ben-Kadmiël. Ihre Verwandten standen ihnen in ihrer Dienstabteilung gegenüber, um nach dem Gebot des Gottesmannes David zu loben und zu preisen." },
      { number: 25, text: "Es waren: Mattanja, Bakbukja und Obadja. Meschullam, Talmon und Akkub waren Torwächter; sie bewachten die Vorratsräume bei den Toren des Tempels." },
      { number: 26, text: "Diese Männer lebten in der Zeit von Jojakim Ben-Jeschua, dem Enkel von Jozadak, und in der Zeit des Statthalters Nehemia und des Priesters und Schriftgelehrten Esra." },
      { number: 27, text: "Zur Einweihung der Stadtmauer holte man die Leviten aus dem ganzen Land nach Jerusalem, um das Freudenfest mit Lobliedern und der festlichen Musik von Zimbeln, Harfen und Zithern zu feiern.", heading: "Die Einweihung der Stadtmauer" },
      { number: 28, text: "Da sammelten sich die Sänger aus den Dörfern rings um Jerusalem und den Siedlungen der Netofatiter," },
      { number: 29, text: "aus Bet-Gilgal und dem Gebiet von Geba und Asmawet, denn sie hatten sich in der Umgebung von Jerusalem Gehöfte gebaut." },
      { number: 30, text: "Nachdem die Priester und Leviten sich selbst den Reinigungszeremonien unterzogen hatten, reinigten sie auch das Volk, die Tore und die Mauer." },
      { number: 31, text: "Daraufhin ließ ich die führenden Männer auf die Mauer steigen und stellte zwei große Festchöre zusammen. Der eine zog oben auf der Mauer nach rechts Richtung Misttor." },
      { number: 32, text: "Hinter ihm ging Hoschaja mit der einen Hälfte der führenden Männer aus Juda" },
      { number: 33, text: "und den Priestern Asarja, Esra, Meschullam," },
      { number: 34, text: "Juda, Benjamin, Schemaja und Jirmeja mit Trompeten." },
      { number: 35, text: "Es folgten Secharja Ben-Jonatan, der von Schemaja, Mattanja, Michaja, Sakkur und Asaf abstammte," },
      { number: 36, text: "und seine Mitbrüder Schemaja, Asarel, Milalai, Gilalai, Maai, Netanel, Juda und Hanani mit den Saiteninstrumenten, wie sie der Gottesmann David einst gespielt hatte. An ihrer Spitze ging der Gesetzeslehrer Esra." },
      { number: 37, text: "Sie zogen weiter zum Quelltor und stiegen auf dem ansteigenden Mauerstück auf Treppen zur Davidsstadt* hinauf, gingen am ehemaligen Palast Davids vorbei und kamen bis zum Wassertor im Osten.", footnotes: ["Die Davidsstadt umfasste das Gebiet des alten Jebus, das von David erobert worden war. Es bildete den Kern Jerusalems."] },
      { number: 38, text: "Der zweite Festchor zog in entgegengesetzter Richtung. Er wurde von der anderen Hälfte der führenden Männer aus Juda und von mir begleitet. Wir zogen zum Ofenturm über die breite Mauer," },
      { number: 39, text: "das Efraïmtor, das Jeschanator, das Fischtor, am Hananel-Turm und dem Turm der Hundert vorbei zum Schaftor. Am Wachttor machten wir Halt." },
      { number: 40, text: "Dann stellten sich die beiden Dankchöre im Haus Gottes auf. Bei mir standen außer der einen Hälfte der führenden Männer" },
      { number: 41, text: "die Priester Eljakim, Maaseja, Mijamin, Michaja, Eljoënai, Secharja und Hananja mit Trompeten" },
      { number: 42, text: "und die Leviten Maaseja, Schemaja, Eleasar, Usi, Johanan, Malkija, Elam und Eser. Dann ließen sich die Sänger unter der Leitung von Jisrachja hören." },
      { number: 43, text: "Anschließend wurden eine Menge Tiere für das Opfermahl geschlachtet. Gott schenkte allen Männern, Frauen und Kindern große Freude. Der Jubel aus Jerusalem war weithin zu hören." },
      { number: 44, text: "An jenem Tag wurden auch Männer als Aufseher über die Vorratsräume eingesetzt, in denen die Abgaben, die ersten Früchte der Ernte und die Zehnten der Erträge gelagert wurden. In diesen Kammern sammelte man von den Feldern der einzelnen Städte die Anteile, die den Priestern und Leviten gesetzlich zukamen. Denn die Juden hatten ihre Freude an den Priestern und Leviten im heiligen Dienst,", heading: "Die Ordnung der Abgaben" },
      { number: 45, text: "die ihrem Gott die Opfer brachten und die Reinigungshandlungen vollzogen. Auch die Sänger und Torwächter versahen ihren Dienst nach den Anordnungen Davids und seines Sohnes Salomo." },
      { number: 46, text: "Denn seit der Zeit Davids und Asafs gab es Vorsteher für die Sänger, die Gott mit ihren Liedern lobten und priesen." },
      { number: 47, text: "Zur Zeit Serubbabels und zur Zeit Nehemias lieferte ganz Israel die Anteile für den täglichen Bedarf der Sänger und Torwächter ab. Und die Gaben, die Gott geweiht waren, brachten sie zu den Leviten, die wiederum den vorgeschriebenen Anteil an die Priester abgaben." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Damals las man dem Volk aus dem Buch des Mose vor und stieß dabei auf die Vorschrift, dass kein Ammoniter und Moabiter* jemals zur Gemeinde Gottes gehören darf.", heading: "Trennung von den Fremden", footnotes: ["Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered, die Ammoniter nordöstlich davon."] },
      { number: 2, text: "Denn diese Völker hatten sich damals geweigert, den Israeliten Brot und Wasser zu geben, und stattdessen dem Magier Bileam viel Geld angeboten, damit er sie verfluchen sollte. Doch unser Gott hatte den Fluch in Segen verwandelt.*", footnotes: ["in Segen verwandelt. Siehe 4. Mose 22-24."] },
      { number: 3, text: "Als die Israeliten dieses Gesetz zu hören bekamen, schlossen sie alle Fremden aus der Gemeinde Israels aus." },
      { number: 4, text: "Schon vorher hatte der Priester Eljaschib, der für die Räumlichkeiten am Haus unseres Gottes verantwortlich war, seinem Verwandten Tobija", heading: "Weitere Reformen Nehemias" },
      { number: 5, text: "einen großen Raum im Tempel zur Verfügung gestellt. Bis dahin hatte man dort das Opfermehl und den Weihrauch aufbewahrt, die entsprechenden Tempelgeräte und den Zehnten von Getreide, Most und Öl, der den Leviten, den Sängern, den Torwächtern und den Priestern zustand." },
      { number: 6, text: "Bei alldem war ich nicht in Jerusalem gewesen, denn im 32. Regierungsjahr* des Königs Artaxerxes von Babylon war ich an den Hof zurückgekehrt und hatte mir erst nach einer längeren Zeit vom König wieder Urlaub erbeten.", footnotes: ["32. Regierungsjahr. 433/2 v.Chr., siehe Nehemia 5,14."] },
      { number: 7, text: "Als ich dann wieder nach Jerusalem kam, sah ich, dass Eljaschib für Tobija einen großen Raum im Vorhof des Tempels eingerichtet hatte." },
      { number: 8, text: "Das missfiel mir sehr und ich ließ alles hinauswerfen, was Tobija gehörte." },
      { number: 9, text: "Dann befahl ich, die Räume zu reinigen und brachte die Gegenstände des Gotteshauses sowie das Speisopfer und den Weihrauch wieder hinein." },
      { number: 10, text: "Ich erfuhr auch, dass die Abgaben für den Unterhalt der Leviten nicht abgeliefert worden waren, sodass sie ihren Dienst am Tempel verlassen hatten, um ihre Felder zu bestellen." },
      { number: 11, text: "Da stellte ich die Vorsteher zur Rede: \"Warum ist der Tempeldienst so vernachlässigt worden?\" Dann ließ ich die Leviten zurückholen und stellte sie wieder an die Arbeit." },
      { number: 12, text: "Als dann das ganze Volk wieder den Zehnten von ihrem Getreide, dem Wein und dem Olivenöl in die Vorratsräume brachte," },
      { number: 13, text: "übertrug ich die Aufsicht darüber dem Priester Schelemja, dem Schreiber Zadok und dem Leviten Pedaja. Als Helfer stellte ich ihnen noch Hanan Ben-Sakkur, den Enkel Mattanjas, zur Seite. Sie alle galten als zuverlässige Männer und sollten für die Verteilung des Zehnten an ihre Brüder verantwortlich sein." },
      { number: 14, text: "\"Denk an mich, mein Gott, und lösch die guten Taten, die ich für dein Haus und den Tempeldienst vollbracht habe, nicht aus deinem Buch aus!\"" },
      { number: 15, text: "Zu derselben Zeit sah ich Leute in Judäa, die am Sabbat in der Kelter Weintrauben auspressten, Getreide vom Feld einbrachten und ihre Esel damit beluden. Sie brachten auch Wein, Trauben, Feigen und andere Lasten am Sabbat nach Jerusalem hinein. Ich verwarnte sie, als sie es an diesem Tag verkaufen wollten." },
      { number: 16, text: "Die Leute von Tyrus, die sich bei uns niedergelassen hatten, brachten Fische und andere Waren in die Stadt und verkauften sie auch am Sabbat an die Juden." },
      { number: 17, text: "Da stellte ich die Vornehmen Judäas zur Rede und hielt ihnen vor: \"Was macht ihr da für eine böse Sache? Ihr schändet den Sabbat!" },
      { number: 18, text: "Haben das nicht schon eure Vorfahren gemacht? Und hat Gott nicht deshalb all das Unglück über uns und diese Stadt gebracht? Wollt ihr durch eure Sabbatschändung seinen Zorn noch größer machen?\"" },
      { number: 19, text: "Deshalb ordnete ich an, die Tore Jerusalems zu schließen, wenn es am Vorabend des Sabbats in den Torwegen dunkel wurde, und sie erst wieder zu öffnen, wenn der Sabbat vorüber war. Auch stellte ich einige meiner Leute an die Tore, damit am Sabbat keine Lasten hereingebracht würden." },
      { number: 20, text: "Nun mussten die Kaufleute und Händler mit all ihren Waren ein- oder zweimal draußen vor Jerusalem übernachten." },
      { number: 21, text: "Ich warnte sie und sagte: \"Warum übernachtet ihr vor der Stadtmauer? Wenn das noch einmal vorkommt, lasse ich euch festnehmen!\" Von dieser Zeit an kamen sie am Sabbat nicht wieder." },
      { number: 22, text: "Darauf befahl ich den Leviten, sie sollten sich reinigen und sich als Wächter an die Tore stellen, damit man den Sabbat heilig halten könne.\"Denk an mich, mein Gott, und rechne mir auch das an! Erbarme dich über mich nach deiner grenzenlosen Güte!\"" },
      { number: 23, text: "Damals wurde ich auch auf einige Juden aufmerksam, die Frauen aus Aschdod, Ammon und Moab geheiratet hatten." },
      { number: 24, text: "Die Hälfte ihrer Kinder redete aschdoditisch oder in einer anderen fremden Sprache und keins von ihnen konnte jüdisch sprechen." },
      { number: 25, text: "Da ging ich mit ihnen ins Gericht und verfluchte sie. Einige von ihnen schlug ich, riss sie an den Haaren und beschwor sie bei Gott: \"Ihr dürft eure Töchter nicht mit deren Söhnen verheiraten und deren Töchter nicht für eure Söhne nehmen!" },
      { number: 26, text: "Selbst Salomo, der König von Israel, hat wegen solcher Frauen schwere Schuld auf sich geladen. Zwar hat es unter den vielen Völkern keinen König wie ihn gegeben und er war der Liebling Gottes und Gott hatte ihn zum König über ganz Israel gemacht. Aber sogar ihn haben die ausländischen Frauen zur Sünde verleitet." },
      { number: 27, text: "Es ist unerhört, dass ihr das gleiche große Unrecht begeht, dass ihr ausländische Frauen heiratet und so unserem Gott untreu werdet!\"" },
      { number: 28, text: "Einer der Söhne von Jojada Ben-Eljaschib, dem Hohen Priester, war der Schwiegersohn des Horoniters Sanballat; den entfernte ich aus meiner Umgebung." },
      { number: 29, text: "\"Mein Gott, vergiss es diesen Leuten nicht, dass sie das Priesteramt entehrt und den Bund gebrochen haben, den du mit den Priestern und Leviten geschlossen hast!\"" },
      { number: 30, text: "So habe ich das Volk von allen fremden Einflüssen gereinigt. Ich stellte Dienstordnungen für die Priester und Leviten auf, die jedem seine Pflichten zuweisen." },
      { number: 31, text: "Ich sorgte auch für die regelmäßige Lieferung des Brennholzes und die Abgabe der ersten Früchte.\"Denk an mich, mein Gott, und lass es mir zugutekommen!\"" },
    ] },
  ],
};